      'dot',
      '-Tsvg',
      `-Gbgcolor=${request.background}`,
      ...['G', 'N', 'E'].flatMap((k) => [`-${k}fontname=Helvetica,Arial,sans-serif`, `-${k}fontcolor=${ink}`]),
